export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface RoomSpec {
  maxNights: number;
  maxGuests: number;
  minStay: number;
  base: number;
  highSurcharge: number;
  extra: (guests: number) => number;
}

// One table carries what actually differs between room types; everything
// else is a single calculation path instead of three copies of it.
const ROOMS: Record<string, RoomSpec> = {
  standard: { maxNights: 14, maxGuests: 2, minStay: 1, base: 80,  highSurcharge: 30,  extra: () => 0 },
  suite:    { maxNights: 21, maxGuests: 4, minStay: 1, base: 150, highSurcharge: 60,  extra: (g) => (g > 2 ? 25 : 0) },
  villa:    { maxNights: 28, maxGuests: 8, minStay: 3, base: 300, highSurcharge: 120, extra: () => 500 },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const loyalty = req.loyaltyYears as number;
  if (!Number.isInteger(loyalty) || loyalty < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const room = ROOMS[req.category as string];
  if (!room) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;
  const season = req.season;

  if (!Number.isInteger(nights) || nights < 1 || nights > room.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (nights < room.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!Number.isInteger(guests) || guests < 1 || guests > room.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }

  const preferred = loyalty >= 3 || req.coupon === "VIP";

  let total = nights * room.base;
  if (season === "high") {
    total += nights * room.highSurcharge;
  }
  if (preferred) {
    total -= Math.floor(total / 10);
  }
  total += room.extra(guests);

  const policy = preferred ? "flex" : "strict";
  const line = `${req.category}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

